package com.esn.smp.gameplay;
import org.bukkit.*;import org.bukkit.enchantments.Enchantment;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.EntityDeathEvent;import org.bukkit.event.entity.EntityDamageByEntityEvent;import org.bukkit.event.block.BlockBreakEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.*;import java.util.*;import java.util.concurrent.ThreadLocalRandom;
public final class MegaCrates implements Listener,org.bukkit.command.CommandExecutor{
 public static final int COUNT=100, ITEMS=11;
 private static NamespacedKey k(String s){return new NamespacedKey("esnsmp",s);}
 public static String name(int t){return "Realm "+String.format("%03d",t+1);}
 private static int power(int t){return 255+(int)Math.round((29745.0*t)/(COUNT-1));}
 private static Material keyMaterial(int t){List<Material> a=new ArrayList<>();for(Material m:Material.values())if(m.isItem()&&m.getMaxStackSize()>=64&&!m.isAir()&&!m.name().contains("SPAWN_EGG"))a.add(m);a.sort(Comparator.comparing(Enum::name));return a.get(Math.floorMod(t,a.size()));}
 public static ItemStack key(int t){ItemStack i=new ItemStack(keyMaterial(t));ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.GOLD+"✦ "+ChatColor.DARK_PURPLE+name(t)+ChatColor.GOLD+" Crate Key ✦");m.setLore(List.of(ChatColor.DARK_GRAY+"━━━━━━━━━━━━━━━━━━━━",ChatColor.LIGHT_PURPLE+"Realm Progression Key",ChatColor.GRAY+"Unlocks: "+ChatColor.WHITE+name(t)+" Crate",ChatColor.GRAY+"Realm Tier: "+ChatColor.GOLD+(t+1)+ChatColor.GRAY+" / "+ChatColor.GOLD+"100",ChatColor.GRAY+"Reward Pool: "+ChatColor.AQUA+ITEMS+" exclusive items",ChatColor.GRAY+"Enchant Power: "+ChatColor.LIGHT_PURPLE+(255+(int)Math.round((9745.0*t)/(COUNT-1))),ChatColor.DARK_GRAY+"Bound to the ESN Realm crate system",ChatColor.DARK_GRAY+"━━━━━━━━━━━━━━━━━━━━"));m.getPersistentDataContainer().set(k("mega_key"),PersistentDataType.INTEGER,t);i.setItemMeta(m);return i;}
 public static boolean isKey(ItemStack i,int t){return i!=null&&i.hasItemMeta()&&Objects.equals(i.getItemMeta().getPersistentDataContainer().get(k("mega_key"),PersistentDataType.INTEGER),t);}
 public static ItemStack item(int t,int s){Material[] a={Material.NETHERITE_SWORD,Material.NETHERITE_AXE,Material.NETHERITE_PICKAXE,Material.NETHERITE_SHOVEL,Material.NETHERITE_HOE,Material.NETHERITE_HELMET,Material.NETHERITE_CHESTPLATE,Material.NETHERITE_LEGGINGS,Material.NETHERITE_BOOTS,Material.BOW,Material.CROSSBOW};String[] n={"Blade","Cleaver","Drill","Spade","Harvester","Crown","Aegis","Legguards","Walkers","Longbow","Repeater"};int base=255+(int)Math.round((9745.0*t)/(COUNT-1));ItemStack i=new ItemStack(a[s]);ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.LIGHT_PURPLE+name(t)+" "+n[s]);m.setLore(realmLore(t,s,base));m.getPersistentDataContainer().set(k("mega_item"),PersistentDataType.STRING,t+":"+s);i.setItemMeta(m);applyRealmEnchants(i,t,s);return i;}
 private static List<String> realmLore(int t,int s,int base){List<String> l=new ArrayList<>();l.add(ChatColor.DARK_PURPLE+"MEGA CRATE TIER "+(t+1));l.add(ChatColor.GOLD+"Power "+base);l.add(ChatColor.AQUA+"REAL ENCHANT LEVELS: "+base);l.add(ChatColor.GRAY+"Bedrock may visually cap vanilla enchant text.");if(s<=1)l.add(ChatColor.LIGHT_PURPLE+"Sharpness/Looting/Fire/Knockback/Smite/Bane: "+base);else if(s<=4)l.add(ChatColor.LIGHT_PURPLE+"Efficiency/Fortune/Silk Touch: "+base);else if(s<=8)l.add(ChatColor.LIGHT_PURPLE+"Protection/Blast/Fire/Projectile/Thorns: "+base);else l.add(ChatColor.LIGHT_PURPLE+"Power/Punch/Flame/Infinity: "+base);l.add(ChatColor.LIGHT_PURPLE+"Unbreaking: "+base);return l;} private static void applyRealmEnchants(ItemStack i,int t,int s){int base=power(t);applyUnsafe(i,Enchantment.UNBREAKING,base);if(s<=1){applyUnsafe(i,Enchantment.SHARPNESS,base);applyUnsafe(i,Enchantment.LOOTING,base);applyUnsafe(i,Enchantment.FIRE_ASPECT,base);applyUnsafe(i,Enchantment.KNOCKBACK,base);applyUnsafe(i,Enchantment.SMITE,base);applyUnsafe(i,Enchantment.BANE_OF_ARTHROPODS,base);if(s==1)applyUnsafe(i,Enchantment.EFFICIENCY,base);}else if(s<=4){applyUnsafe(i,Enchantment.EFFICIENCY,base);applyUnsafe(i,Enchantment.FORTUNE,base);applyUnsafe(i,Enchantment.SILK_TOUCH,base);if(s==4)applyUnsafe(i,Enchantment.LOOTING,base);}else if(s<=8){applyUnsafe(i,Enchantment.PROTECTION,base);applyUnsafe(i,Enchantment.BLAST_PROTECTION,base);applyUnsafe(i,Enchantment.FIRE_PROTECTION,base);applyUnsafe(i,Enchantment.PROJECTILE_PROTECTION,base);applyUnsafe(i,Enchantment.THORNS,base);if(s==5)applyUnsafe(i,Enchantment.RESPIRATION,base);if(s==5)applyUnsafe(i,Enchantment.AQUA_AFFINITY,base);if(s==8)applyUnsafe(i,Enchantment.FEATHER_FALLING,base);if(s==8)applyUnsafe(i,Enchantment.DEPTH_STRIDER,base);if(s==8)applyUnsafe(i,Enchantment.SOUL_SPEED,base);}else{applyUnsafe(i,Enchantment.POWER,base);applyUnsafe(i,Enchantment.PUNCH,base);applyUnsafe(i,Enchantment.FLAME,base);applyUnsafe(i,Enchantment.INFINITY,base);if(s==10){applyUnsafe(i,Enchantment.QUICK_CHARGE,base);applyUnsafe(i,Enchantment.PIERCING,base);applyUnsafe(i,Enchantment.MULTISHOT,base);}}}
 public boolean onCommand(org.bukkit.command.CommandSender sender,org.bukkit.command.Command command,String label,String[] args){if(!sender.hasPermission("esnsmp.admin")){sender.sendMessage(ChatColor.RED+"You need esnsmp.admin.");return true;}if(args.length!=1){sender.sendMessage(ChatColor.YELLOW+"/megacratekey <1-100>");return true;}int realm;try{realm=Integer.parseInt(args[0]);}catch(Exception ex){sender.sendMessage(ChatColor.RED+"Realm must be 1-100.");return true;}if(realm<1||realm>100){sender.sendMessage(ChatColor.RED+"Realm must be 1-100.");return true;}if(sender instanceof Player p){p.getInventory().addItem(key(realm-1));p.sendMessage(ChatColor.GREEN+"Given "+name(realm-1)+" Crate Key.");}else sender.sendMessage(ChatColor.RED+"Run this command as a player.");return true;}
 private static void repair(ItemStack i){if(i==null||!i.hasItemMeta())return;ItemMeta m=i.getItemMeta();String v=m.getPersistentDataContainer().get(k("mega_item"),PersistentDataType.STRING);if(v==null)return;try{String[] a=v.split(":");int t=Integer.parseInt(a[0]),s=Integer.parseInt(a[1]),base=power(t);m.setLore(realmLore(t,s,base));i.setItemMeta(m);for(Enchantment e:new HashSet<>(i.getEnchantments().keySet()))i.removeEnchantment(e);applyRealmEnchants(i,t,s);}catch(Exception ignored){}}
 @EventHandler public void repairJoin(org.bukkit.event.player.PlayerJoinEvent e){for(ItemStack i:e.getPlayer().getInventory().getContents())repair(i);for(ItemStack i:e.getPlayer().getEnderChest().getContents())repair(i);}
 @EventHandler public void repairHeld(org.bukkit.event.player.PlayerItemHeldEvent e){repair(e.getPlayer().getInventory().getItem(e.getNewSlot()));}
 @EventHandler public void repairOpen(org.bukkit.event.inventory.InventoryOpenEvent e){for(ItemStack i:e.getInventory().getContents())repair(i);}
 private static void applyUnsafe(ItemStack i,Enchantment e,int level){int v=Math.max(1,Math.min(30000,level));i.addUnsafeEnchantment(e,v);if(i.getEnchantmentLevel(e)!=v)throw new IllegalStateException("Realm enchant write failed: "+e.getKey()+" expected "+v+" got "+i.getEnchantmentLevel(e));}
 private static int tier(ItemStack i){if(i==null||!i.hasItemMeta())return -1;String v=i.getItemMeta().getPersistentDataContainer().get(k("mega_item"),PersistentDataType.STRING);if(v==null)return -1;try{return Integer.parseInt(v.split(":")[0]);}catch(Exception ex){return -1;}}
 private static double scale(int t){return t<0?1.0:1.0+power(t)/255.0;}
 @EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true) public void realmDamage(EntityDamageByEntityEvent e){Player p=e.getDamager() instanceof Player q?q:e.getDamager() instanceof Projectile pr&&pr.getShooter() instanceof Player q?q:null;if(p==null)return;int t=tier(p.getInventory().getItemInMainHand());if(t<0)return;double mult=Math.min(12.0,scale(t));e.setDamage(e.getDamage()*mult);}
 @EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true) public void realmMine(BlockBreakEvent e){ItemStack tool=e.getPlayer().getInventory().getItemInMainHand();int t=tier(tool);if(t<0)return;int level=power(t);if(ThreadLocalRandom.current().nextDouble()<Math.min(.85,level/12000.0)){Collection<ItemStack> drops=e.getBlock().getDrops(tool,e.getPlayer());for(ItemStack d:drops){ItemStack bonus=d.clone();bonus.setAmount(Math.min(bonus.getMaxStackSize(),Math.max(1,(int)Math.ceil(d.getAmount()*Math.min(8.0,level/1000.0)))));e.getPlayer().getInventory().addItem(bonus).values().forEach(z->e.getPlayer().getWorld().dropItemNaturally(e.getBlock().getLocation(),z));}}}
 public static ItemStack[] pool(int t){ItemStack[] a=new ItemStack[ITEMS];for(int s=0;s<ITEMS;s++)a[s]=item(t,s);return a;}
 @EventHandler public void death(EntityDeathEvent e){Player p=e.getEntity().getKiller();if(p==null)return;Set<String> z=e.getEntity().getScoreboardTags();boolean world=z.contains("esnWorldBoss"),boss=world||z.contains("esnSwampBoss")||z.contains("esnBiomeBoss");if(boss)return;if(ThreadLocalRandom.current().nextDouble()<.35)e.getDrops().add(key(ThreadLocalRandom.current().nextInt(COUNT)));}
}